/* From Uiverse.io by emmanuelh-dev - Tags: card, calculator */
.__UIV_SCOPE__ .calculator {
  border: 1px solid rgb(179, 179, 179);
  border-radius: 0.375rem;
  width: 190px;
  height: 254px;
  font-family: Arial, sans-serif;
  margin: 0 auto;
  padding: 10px;
}

.__UIV_SCOPE__ .output {
  border: 1px solid #ccc;
  border-radius: 0.375rem;
  height: 40px;
  margin-bottom: 10px;
  margin-top: 10px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding-right: 10px;
}

.__UIV_SCOPE__ .result {
  font-size: 20px;
}

.__UIV_SCOPE__ .buttons {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-gap: 5px;
}

.__UIV_SCOPE__ button {
  border: none;
  border-radius: 0.375rem;
  padding: 10px;
  background-color: #eee;
  cursor: pointer;
  font-size: 16px;
}

.__UIV_SCOPE__ button:hover {
  background-color: #ddd;
}

.__UIV_SCOPE__ button:active {
  background-color: #ccc;
}

.__UIV_SCOPE__ .bg-green {
  background-color: rgba(0, 177, 29, 0.651);
  color: white;
}

.__UIV_SCOPE__ .bg-green:hover {
  background-color: rgba(0, 231, 39, 0.651);
  color: white;
}

.__UIV_SCOPE__ .bg-red {
  background-color: rgba(223, 4, 4, 0.651);
  color: white;
}

.__UIV_SCOPE__ .bg-red:hover {
  background-color: rgba(255, 1, 1, 0.651);
  color: white;
}
